import os
from openpyxl import load_workbook
from openpyxl.utils import get_column_letter

os.makedirs('/root/output', exist_ok=True)
path='/root/data/workbook.xlsx'
wb=load_workbook(path, data_only=False)
print('Sheets:', wb.sheetnames)
ws=wb['Task']

print('\nTask!A10:L10 values and types:')
for col in range(1,13):
    v=ws.cell(row=10, column=col).value
    print(f"{get_column_letter(col)}10\t{v!r}\t{type(v).__name__}")

ranges=[(12,17),(19,24),(26,31)]
print('\nTask!D series codes:')
for a,b in ranges:
    for r in range(a,b+1):
        v=ws[f'D{r}'].value
        print(f"D{r}\t{v!r}\t{type(v).__name__}")

blocks=[(12,17),(19,24),(26,31),(35,40),(42,47),(50,50)]
print('\nExisting content in Task blocks H-L:')
for a,b in blocks:
    print(f"-- Rows {a}-{b}")
    for r in range(a,b+1):
        for c in range(8,13):
            addr=f"{get_column_letter(c)}{r}"
            v=ws.cell(row=r, column=c).value
            print(f"{addr}\t{v!r}\t{type(v).__name__}")

print('\nTask!A33:L50:')
for r in range(33,51):
    vals=[ws.cell(row=r, column=c).value for c in range(1,13)]
    print(f"Row {r}: {vals!r}")

wsd=wb['Data']
print('\nData! rows 19-40 cols A-Z value|type:')
for r in range(19,41):
    row=[]
    for c in range(1,27):
        v=wsd.cell(row=r, column=c).value
        if v is None:
            row.append('')
        else:
            row.append(f"{v!r}|{type(v).__name__}")
    print(f"Row {r}:\n  "+'\t'.join(row))

import re

def is_year(x):
    if isinstance(x,(int,float)) and 1900<=x<=2100:
        return True
    if isinstance(x,str) and re.fullmatch(r'\d{4}', x.strip()):
        return True
    return False

print('\nHeuristic header-row check (rows 19-23):')
for r in range(19,24):
    years=[]
    for c in range(1,27):
        v=wsd.cell(row=r, column=c).value
        if is_year(v):
            years.append((get_column_letter(c), v, type(v).__name__))
    if years:
        print('Row', r, 'year-like cells:', years)

