import re
from openpyxl import load_workbook
from openpyxl.utils import get_column_letter

wb=load_workbook('/root/data/workbook.xlsx', data_only=False)
ws=wb['Data']

def is_year(v):
    if isinstance(v,(int,float)) and 1900<=v<=2100 and float(v).is_integer():
        return True
    if isinstance(v,str) and re.fullmatch(r'\d{4}', v.strip()):
        return True
    return False

year_cells=[]
for row in ws.iter_rows(values_only=False):
    for cell in row:
        v=cell.value
        if is_year(v):
            year_cells.append((cell.coordinate, v, type(v).__name__))

print('Found year-like cells:', len(year_cells))
for item in year_cells[:200]:
    print(item)

# Also search for the string 'Year' or similar headers
keywords=['Year','year','FY','Fiscal']
found=[]
for row in ws.iter_rows(values_only=False):
    for cell in row:
        v=cell.value
        if isinstance(v,str):
            for k in keywords:
                if k in v:
                    found.append((cell.coordinate, v))
                    break
print('\nHeader keyword hits:', len(found))
for f in found[:50]:
    print(f)

# Determine max_column and max_row with content
max_r=0; max_c=0
for r in range(1, ws.max_row+1):
    for c in range(1, ws.max_column+1):
        if ws.cell(row=r,column=c).value is not None:
            if r>max_r: max_r=r
            if c>max_c: max_c=c
print('\nws.max_row', ws.max_row, 'ws.max_column', ws.max_column)
print('content max row', max_r, 'max col', max_c, get_column_letter(max_c))
